package blockbranch.realistic;
import java.util.*;
public final class SnowySlopesCheck{
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var e=new GroundEcology.Field(d::sample,c);int selected=0,scree=0,retained=0,fromBare=0;for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){boolean sc=AlpineScree.contains(x,z,d::sample),snow=SnowySlopes.contains(x,z,d,c);if(sc){scree++;if(!snow)retained++;}if(!snow)continue;selected++;String old=PlacementBaseline.definition31(seed,x,z,d,c);require(old.equals(sc?"scree":"placeholder"),"Only old scree or genuinely bare cold slopes are partitioned");if(!sc)fromBare++;var cl=c.sample(x,z,d::sample);double slope=SlopeCorrection.slope(d,x,z);require(slope>.4&&slope<=.9&&cl.meanTemperatureC()>=-14&&cl.meanTemperatureC()<-2&&cl.moisture()>=.35,"Actual cold moist moderate mountain faces");require(!SnowyPlains.contains(x,z,d,c)&&!ColdTundra.contains(x,z,d,c)&&!BorealWoodland.contains(seed,x,z,d,c)&&!ColdSteppe.contains(x,z,d,c),"Preserve plains,tundra,boreal and steppe");}require(selected>100&&retained>scree*.75&&fromBare>20,"Meaningful slopes and retained exposed scree,not an altitude-band patch");var p=blockbranch.realistic.SnowySlopesFixtures.fixture(d,seed);int count=0,gaps=0;var layers=new HashSet<Integer>();var arrays=new LinkedHashMap<String,int[]>();for(int cz=(p.z()>>4)-2;cz<=(p.z()>>4)+2;cz++)for(int cx=(p.x()>>4)-2;cx<=(p.x()>>4)+2;cx++){var a=OpenSnowCover.slopesColumn(seed,cx,cz,new int[0],d,c,e);require(a.length<=256,"One terrain-snow state per column cell bound");count+=a.length;gaps+=256-a.length;arrays.put(cx+","+cz,a);for(int v:a){int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,wx=cx*16+(k&15),wz=cz*16+((k>>>4)&15),y=(k>>>8)+TerrainShape.FLOOR;require(SnowyTaiga.snow(v&blockbranch.cubic.CanopyLayer.STATE_MASK)&&y==d.sample(wx,wz).height()+1&&d.sample(wx,wz).waterLevel()==DrainageNetwork.DRY&&d.channelAt(wx,wz).edge()<0,"Dry supported terrain snow preserves channels");layers.add(v&blockbranch.cubic.CanopyLayer.STATE_MASK);}}require(count>1000&&layers.size()>=2,"Coherent variable-depth slope snow");var keys=new ArrayList<>(arrays.keySet());Collections.reverse(keys);for(String key:keys){var q=key.split(",");require(Arrays.equals(arrays.get(key),OpenSnowCover.slopesColumn(seed,Integer.parseInt(q[0]),Integer.parseInt(q[1]),new int[0],d,c,e)),"Negative-coordinate seam/order stability");}int cx=p.x()>>4,cz=p.z()>>4;var strip=OpenSnowCover.column(seed,cx,cz,new int[0],d,e,(wx,wz)->Math.floorMod(wx,4)==1,true);require(strip.length>0,"Non-quart material eligibility is represented");for(int v:strip){int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS;require(Math.floorMod(cx*16+(k&15),4)==1,"Snow must not spread a selected block across its quart cell");}System.out.println("SNOWY_SLOPES seed="+seed+" selected="+selected+" retainedScree="+retained+" priorScree="+scree+" fromBare="+fromBare+" point="+p+" snow="+count+" gaps="+gaps+" layers="+layers);}
 System.out.println("SNOWY_SLOPES_CLIMATE_ASPECT_RETAINED_SUBSTRATE_SEAMS_PASS");}
 private static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
